'use strict';

// Bundles packages/shared into one plain script the processor webview can load.
//
// The shared text pipeline and the insertion safety rules are the source of
// truth for every ColdVoice platform, and they are CommonJS. Rather than fork
// them into Rust — where they would drift from the Windows build within a
// release — the Linux app runs them as-is. This walks the require graph and
// wraps each module in a tiny loader. No dependencies, so it runs anywhere the
// repo is checked out.

const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const SHARED = path.join(REPO_ROOT, 'packages', 'shared');
const OUT = path.join(__dirname, '..', 'ui', 'vendor', 'shared.js');

const ENTRIES = {
  textProcessing: path.join(SHARED, 'text-processing', 'src', 'index.js'),
  inputDetection: path.join(SHARED, 'input-detection', 'index.js'),
};

function key(file) {
  return path.relative(SHARED, file).split(path.sep).join('/');
}

function resolve(fromFile, request) {
  const base = path.resolve(path.dirname(fromFile), request);
  for (const candidate of [base, `${base}.js`, path.join(base, 'index.js')]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
  }
  throw new Error(`Cannot resolve ${request} from ${fromFile}`);
}

const modules = new Map();

function collect(file) {
  const id = key(file);
  if (modules.has(id)) return id;
  const source = fs.readFileSync(file, 'utf8');
  modules.set(id, source);
  const requireRe = /require\(\s*['"]([^'"]+)['"]\s*\)/g;
  let match;
  while ((match = requireRe.exec(source)) !== null) {
    const request = match[1];
    if (!request.startsWith('.')) {
      throw new Error(`Unexpected bare require "${request}" in ${id}. The shared packages must stay dependency-free.`);
    }
    collect(resolve(file, request));
  }
  return id;
}

const entryIds = {};
for (const [name, file] of Object.entries(ENTRIES)) {
  entryIds[name] = collect(file);
}

const parts = [];
parts.push('// GENERATED by apps/linux-tauri/tools/bundle-shared.js — do not edit.');
parts.push('// Source of truth: packages/shared/*');
parts.push('(function () {');
parts.push('  var defs = {};');
parts.push('  var cache = {};');
parts.push('  function dirname(p) { var i = p.lastIndexOf("/"); return i < 0 ? "" : p.slice(0, i); }');
parts.push('  function normalize(p) {');
parts.push('    var out = [];');
parts.push('    p.split("/").forEach(function (seg) {');
parts.push('      if (!seg || seg === ".") return;');
parts.push('      if (seg === "..") { out.pop(); return; }');
parts.push('      out.push(seg);');
parts.push('    });');
parts.push('    return out.join("/");');
parts.push('  }');
parts.push('  function makeRequire(from) {');
parts.push('    return function (request) {');
parts.push('      var base = normalize(dirname(from) + "/" + request);');
parts.push('      var id = defs[base] ? base : (defs[base + ".js"] ? base + ".js" : base + "/index.js");');
parts.push('      return load(id);');
parts.push('    };');
parts.push('  }');
parts.push('  function load(id) {');
parts.push('    if (cache[id]) return cache[id].exports;');
parts.push('    var module = { exports: {} };');
parts.push('    cache[id] = module;');
parts.push('    defs[id](module, module.exports, makeRequire(id));');
parts.push('    return module.exports;');
parts.push('  }');

for (const [id, source] of modules) {
  parts.push(`  defs[${JSON.stringify(id)}] = function (module, exports, require) {`);
  parts.push(source.replace(/\r\n/g, '\n').replace(/^/gm, '    ').replace(/\s+$/, ''));
  parts.push('  };');
}

parts.push('  window.ColdVoiceShared = {');
parts.push(`    textProcessing: load(${JSON.stringify(entryIds.textProcessing)}),`);
parts.push(`    inputDetection: load(${JSON.stringify(entryIds.inputDetection)}),`);
parts.push('  };');
parts.push('})();');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, `${parts.join('\n')}\n`);
console.log(`bundled ${modules.size} shared modules -> ${path.relative(process.cwd(), OUT)}`);
